## Problem 2 — self time per function

Edit `ex2/solution.ts`. Implement:

```ts
export interface CallFrame {
  functionName: string;
  url: string;
  lineNumber: number;
}
export interface ProfileNode { id: number; callFrame: CallFrame; hitCount?: number; children?: number[]; }
export interface CpuProfile { nodes: ProfileNode[]; startTime: number; endTime: number; samples?: number[]; timeDeltas?: number[]; }

export interface SelfTime { key: string; functionName: string; hits: number; selfUs: number; share: number; }

export function selfTimeByFunction(profile: CpuProfile, options?: { top?: number }): SelfTime[]
```

Group nodes by call frame identity, sum their `hitCount`, and convert hits to
microseconds using the **average** sample interval:
`(endTime - startTime) / totalHits`. `share` is the fraction of all hits, 0-1.

The grouping key is `functionName@url:lineNumber`, because two different
functions can share a name and merging them produces a report that points at
the wrong file. An anonymous frame has `functionName: ""` — report it as
`(anonymous)`.

Sort by `selfUs` descending, tie-broken by key, and return the top
`options.top` (default 10).

```ts
selfTimeByFunction(profile, { top: 1 });
// [{ key: "parseRow@file:///app/csv.js:87", functionName: "parseRow",
//    hits: 412, selfUs: 411_900, share: 0.41 }]
```

```
uv run dojo test node v3nc05_cpu_profiling ex2
```

references.solution.ts:
// v3nc05_cpu_profiling / ex2 - reference solution (author only, used by `dojo verify`).

export interface CallFrame {
  functionName: string;
  url: string;
  lineNumber: number;
}

export interface ProfileNode {
  id: number;
  callFrame: CallFrame;
  hitCount?: number;
  children?: number[];
}

export interface CpuProfile {
  nodes: ProfileNode[];
  startTime: number;
  endTime: number;
  samples?: number[];
  timeDeltas?: number[];
}

export interface SelfTime {
  key: string;
  functionName: string;
  hits: number;
  selfUs: number;
  share: number;
}

function keyOf(frame: CallFrame): string {
  // Name alone merges two different `validate` functions from two files into
  // one line that points at neither.
  const name = frame.functionName === "" ? "(anonymous)" : frame.functionName;
  return `${name}@${frame.url}:${frame.lineNumber}`;
}

export function selfTimeByFunction(profile: CpuProfile, options: { top?: number } = {}): SelfTime[] {
  const totalHits = profile.nodes.reduce((sum, node) => sum + (node.hitCount ?? 0), 0);
  // startTime/endTime are microseconds in a .cpuprofile. The average interval
  // is what every mainstream tool uses; timeDeltas would be marginally more
  // accurate and is rarely worth the code.
  const usPerHit = totalHits > 0 ? (profile.endTime - profile.startTime) / totalHits : 0;

  const totals = new Map<string, SelfTime>();
  for (const node of profile.nodes) {
    const hits = node.hitCount ?? 0;
    if (hits === 0) continue;
    const key = keyOf(node.callFrame);
    const entry = totals.get(key);
    if (entry) {
      entry.hits += hits;
    } else {
      totals.set(key, {
        key,
        functionName: node.callFrame.functionName === "" ? "(anonymous)" : node.callFrame.functionName,
        hits,
        selfUs: 0,
        share: 0,
      });
    }
  }

  for (const entry of totals.values()) {
    entry.selfUs = entry.hits * usPerHit;
    // Guarded: 0/0 is NaN, and every NaN comparison is false, which would make
    // the sort below silently do nothing.
    entry.share = totalHits > 0 ? entry.hits / totalHits : 0;
  }

  return [...totals.values()]
    .sort((a, b) => b.selfUs - a.selfUs || a.key.localeCompare(b.key))
    .slice(0, options.top ?? 10);
}

exercises.hints:
## Hint 1

Self time needed no tree; total time needs nothing but the tree. Build a map
from node id to node, find the root (the node no one lists as a child), and
walk.

The walk carries two things: the subtree's hit count coming back up, and the
set of frame keys currently on the path going down.

## Hint 2

```ts
function walk(id: number, onPath: Set<string>): number {
  const node = byId.get(id)!;
  const key = keyOf(node.callFrame);
  const fresh = !onPath.has(key);
  if (fresh) onPath.add(key);
  let subtree = node.hitCount ?? 0;
  for (const child of node.children ?? []) subtree += walk(child, onPath);
  if (fresh) { totals.get(key)!.totalHits += subtree; onPath.delete(key); }
  return subtree;
}
```

Note where the credit is applied: only at the *outermost* occurrence of a
frame on the path, which is exactly "once per sample".

## Hint 3

Deep recursion in the profiled program means deep recursion in your walk. A
stack thousands of frames deep will overflow yours — a real tool uses an
explicit stack, and if you do, be careful to keep the "leaving this node" step
that removes the key from the path set.

The decision left to you: whether to recurse or iterate. Both are correct
here; note the limitation of the one you choose.

references.solution.ts:
// v3nc05_cpu_profiling / ex3 - reference solution (author only, used by `dojo verify`).

interface Frame {
  functionName: string;
  url: string;
  lineNumber: number;
}

interface Node {
  id: number;
  callFrame: Frame;
  hitCount?: number;
  children?: number[];
}

export interface TotalTime {
  key: string;
  functionName: string;
  totalHits: number;
  selfHits: number;
  share: number;
}

const keyOf = (frame: Frame): string =>
  `${frame.functionName === "" ? "(anonymous)" : frame.functionName}@${frame.url}:${frame.lineNumber}`;

export function totalTimeByFunction(
  profile: { nodes: Node[] },
  options: { top?: number } = {},
): TotalTime[] {
  const byId = new Map(profile.nodes.map((node) => [node.id, node]));
  const childIds = new Set<number>();
  for (const node of profile.nodes) for (const child of node.children ?? []) childIds.add(child);
  const root = profile.nodes.find((node) => !childIds.has(node.id));
  if (!root) return [];

  const totals = new Map<string, TotalTime>();
  const ensure = (node: Node): TotalTime => {
    const key = keyOf(node.callFrame);
    let entry = totals.get(key);
    if (!entry) {
      entry = {
        key,
        functionName: node.callFrame.functionName === "" ? "(anonymous)" : node.callFrame.functionName,
        totalHits: 0,
        selfHits: 0,
        share: 0,
      };
      totals.set(key, entry);
    }
    return entry;
  };

  let allHits = 0;
  const onPath = new Set<string>();

  // Recursive walk: a profile of a deeply recursive program can overflow this,
  // and a production tool uses an explicit stack for that reason.
  const walk = (id: number): number => {
    const node = byId.get(id);
    if (!node) return 0;
    const entry = ensure(node);
    const hits = node.hitCount ?? 0;
    entry.selfHits += hits;
    allHits += hits;

    // Credit the subtree only at the outermost occurrence of this frame on the
    // path: otherwise a recursive function reports 250% of the runtime.
    const fresh = !onPath.has(entry.key);
    if (fresh) onPath.add(entry.key);

    let subtree = hits;
    for (const child of node.children ?? []) subtree += walk(child);

    if (fresh) {
      entry.totalHits += subtree;
      onPath.delete(entry.key);
    }
    return subtree;
  };

  walk(root.id);

  const list = [...totals.values()];
  for (const entry of list) entry.share = allHits > 0 ? entry.totalHits / allHits : 0;
  return list
    .sort((a, b) => b.totalHits - a.totalHits || a.key.localeCompare(b.key))
    .slice(0, options.top ?? 10);
}

