```

references.solution.ts:
// v3nc05_cpu_profiling / ex6 - reference solution (author only, used by `dojo verify`).
import { monitorEventLoopDelay, performance } from "node:perf_hooks";

export interface LoopHealth {
  meanDelayMs: number;
  p99DelayMs: number;
  maxDelayMs: number;
  utilization: number;
  verdict: "healthy" | "saturated" | "blocked" | "idle-but-slow";
}

export async function measureLoopHealth(
  work: () => void | Promise<void>,
  options: { resolutionMs?: number; p99WarnMs?: number } = {},
): Promise<LoopHealth> {
  const p99WarnMs = options.p99WarnMs ?? 50;
  // Measures lateness: libuv is asked to fire every `resolution` ms and the
  // histogram records how far off it was. The resolution is a floor on what
  // you can observe.
  const histogram = monitorEventLoopDelay({ resolution: options.resolutionMs ?? 10 });
  histogram.enable();
  const baseline = performance.eventLoopUtilization();

  try {
    await work();
  } finally {
    histogram.disable();
  }

  // Passing the baseline gives utilisation for the window, not since boot.
  const { utilization } = performance.eventLoopUtilization(baseline);

  // Everything the histogram reports is nanoseconds.
  const NS = 1e6;
  const meanDelayMs = histogram.mean / NS;
  const p99DelayMs = histogram.percentile(99) / NS;
  const maxDelayMs = histogram.max / NS;

  let verdict: LoopHealth["verdict"] = "healthy";
  if (maxDelayMs >= 50 && maxDelayMs >= 10 * p99DelayMs) {
    // One enormous spike against a calm p99: a single synchronous stall, not
    // steady pressure.
    verdict = "blocked";
  } else if (utilization >= 0.8 && p99DelayMs >= p99WarnMs) {
    verdict = "saturated";
  } else if (utilization < 0.4 && p99DelayMs >= p99WarnMs) {
    // The loop is not busy and callbacks are still late: threadpool
    // saturation, a cgroup CPU quota, a noisy host, or GC pauses. None of
    // those are fixed by optimising JavaScript.
    verdict = "idle-but-slow";
  }

  return { meanDelayMs, p99DelayMs, maxDelayMs, utilization, verdict };
}

