## Challenge — the report

Edit `challenge/solution.ts`. Turn a raw profile into something someone can
act on:

```ts
export interface Recommendation {
  key: string;
  functionName: string;
  selfShare: number;
  totalShare: number;
  callers: string[];          // the path from the root to this frame's heaviest occurrence
  category: "javascript" | "gc" | "native" | "idle";
  advice: string;
}

export interface Report {
  totalSamples: number;
  gcShare: number;
  idleShare: number;
  recommendations: Recommendation[];
  summary: string;
}

export function optimisationReport(
  profile: { nodes: Array<{ id: number; callFrame: { functionName: string; url: string; lineNumber: number }; hitCount?: number; children?: number[] }>; startTime: number; endTime: number },
  options?: { top?: number; minShare?: number },
): Report
```

Requirements:

- rank by self share, dropping anything below `minShare` (default 0.02);
- classify each frame: `(garbage collector)` → `gc`, `(idle)`/`(program)` →
  `idle`, a frame whose `url` is empty or starts with `node:` → `native`,
  anything else → `javascript`;
- `advice` differs by category — a JavaScript frame is a code change, a GC
  frame redirects to allocation, a native frame is a library decision, and an
  idle frame means you are not CPU-bound;
- `callers` is the root-to-frame path of that frame's heaviest node;
- `summary` is one sentence naming the dominant category and the top frame.

```
uv run dojo test node v3nc05_cpu_profiling challenge
```

references.solution.ts:
// v3nc05_cpu_profiling / challenge - reference solution (author only, used by `dojo verify`).

interface Frame {
  functionName: string;
  url: string;
  lineNumber: number;
}

interface Node {
  id: number;
  callFrame: Frame;
  hitCount?: number;
  children?: number[];
}

export interface Recommendation {
  key: string;
  functionName: string;
  selfShare: number;
  totalShare: number;
  callers: string[];
  category: "javascript" | "gc" | "native" | "idle";
  advice: string;
}

export interface Report {
  totalSamples: number;
  gcShare: number;
  idleShare: number;
  recommendations: Recommendation[];
  summary: string;
}

const nameOf = (frame: Frame): string =>
  frame.functionName === "" ? "(anonymous)" : frame.functionName;
const keyOf = (frame: Frame): string => `${nameOf(frame)}@${frame.url}:${frame.lineNumber}`;

function categorise(frame: Frame): Recommendation["category"] {
  const name = frame.functionName;
  if (name === "(garbage collector)") return "gc";
  if (name === "(idle)" || name === "(program)" || name === "(root)") return "idle";
  if (frame.url === "" || frame.url.startsWith("node:")) return "native";
  return "javascript";
}

const ADVICE: Record<Recommendation["category"], string> = {
  javascript: "Change this function: it is your code and it is on the CPU. Look for work in a loop, a regex, or a per-item allocation.",
  gc: "Not a function to optimise. This is allocation pressure - produce fewer or shorter-lived objects, and profile the heap instead.",
  native: "A built-in or native module is doing the work. Call it less, batch it, or choose a different one; there is no local edit here.",
  idle: "The CPU was waiting, not working. This process is not CPU-bound in this window - look at I/O, downstream latency and queueing.",
};

export function optimisationReport(
  profile: { nodes: Node[]; startTime: number; endTime: number },
  options: { top?: number; minShare?: number } = {},
): Report {
  const byId = new Map(profile.nodes.map((node) => [node.id, node]));
  const childIds = new Set<number>();
  for (const node of profile.nodes) for (const child of node.children ?? []) childIds.add(child);
  const root = profile.nodes.find((node) => !childIds.has(node.id));

  const totalSamples = profile.nodes.reduce((sum, node) => sum + (node.hitCount ?? 0), 0);
  const share = (hits: number): number => (totalSamples > 0 ? hits / totalSamples : 0);

  // One walk gives the parent map (for caller paths), the subtree sums (for
  // total share) and the per-key aggregates.
  const parent = new Map<number, number>();
  const subtree = new Map<number, number>();
  const selfByKey = new Map<string, { hits: number; frame: Frame; heaviest: Node }>();
  const totalByKey = new Map<string, number>();
  const onPath = new Set<string>();

  const walk = (id: number): number => {
    const node = byId.get(id);
    if (!node) return 0;
    const key = keyOf(node.callFrame);
    const hits = node.hitCount ?? 0;

    const entry = selfByKey.get(key);
    if (!entry) selfByKey.set(key, { hits, frame: node.callFrame, heaviest: node });
    else {
      entry.hits += hits;
      if (hits > (entry.heaviest.hitCount ?? 0)) entry.heaviest = node;
    }

    const fresh = !onPath.has(key);
    if (fresh) onPath.add(key);

    let total = hits;
    for (const childId of node.children ?? []) {
      parent.set(childId, id);
      total += walk(childId);
    }
    subtree.set(id, total);

    if (fresh) {
      // Once per sample, so a recursive frame cannot exceed 100%.
      totalByKey.set(key, (totalByKey.get(key) ?? 0) + total);
      onPath.delete(key);
    }
    return total;
  };

  if (root) walk(root.id);

  const pathTo = (node: Node): string[] => {
    const path: string[] = [];
    let at: number | undefined = node.id;
    while (at !== undefined) {
      const current = byId.get(at);
      if (!current) break;
      path.push(nameOf(current.callFrame));
      at = parent.get(at);
    }
    return path.reverse();
  };

  const minShare = options.minShare ?? 0.02;
  const recommendations: Recommendation[] = [];
  let gcHits = 0;
  let idleHits = 0;

  for (const [key, entry] of selfByKey) {
    const category = categorise(entry.frame);
    if (category === "gc") gcHits += entry.hits;
    if (category === "idle") idleHits += entry.hits;
    const selfShare = share(entry.hits);
    // A tool that reports everything reports nothing.
    if (selfShare < minShare) continue;
    recommendations.push({
      key,
      functionName: nameOf(entry.frame),
      selfShare,
      totalShare: share(totalByKey.get(key) ?? entry.hits),
      callers: pathTo(entry.heaviest),
      category,
      advice: ADVICE[category],
    });
  }

  recommendations.sort((a, b) => b.selfShare - a.selfShare || a.key.localeCompare(b.key));
  const trimmed = recommendations.slice(0, options.top ?? 10);
  const top = trimmed.find((entry) => entry.category !== "idle") ?? trimmed[0];

  const summary = top
    ? `${(top.selfShare * 100).toFixed(0)}% of samples are in ${top.functionName} (${top.category}); ` +
      `GC accounts for ${(share(gcHits) * 100).toFixed(0)}% and idle for ${(share(idleHits) * 100).toFixed(0)}%.`
    : "No frame cleared the reporting threshold; profile for longer or at a finer interval.";

  return {
    totalSamples,
    gcShare: share(gcHits),
    idleShare: share(idleHits),
    recommendations: trimmed,
    summary,
  };
}

