## Review — which kind of slow is it?

Edit `review1/solution.ts`. Implement:

```ts
export interface Signals {
  utilization: number;        // 0..1, from eventLoopUtilization
  loopDelayP99Ms: number;
  gcShare: number;            // 0..1, share of CPU samples in (garbage collector)
  topFrameSelfShare: number;  // 0..1, the largest single self-time share
}

export type Diagnosis =
  | { kind: "cpu-hot-spot"; nextStep: string }
  | { kind: "gc-pressure"; nextStep: string }
  | { kind: "blocking-call"; nextStep: string }
  | { kind: "io-bound"; nextStep: string }
  | { kind: "healthy"; nextStep: string };

export function classifyBottleneck(signals: Signals): Diagnosis
```

Apply the rules **in this order** — the order is the content of the exercise,
because several conditions can be true at once and only the first one is
actionable:

1. `gcShare >= 0.25` → `"gc-pressure"`;
2. `utilization >= 0.7` and `topFrameSelfShare >= 0.3` → `"cpu-hot-spot"`;
3. `utilization >= 0.7` → `"blocking-call"` (busy, but the cost is spread —
   or hidden in one long synchronous call the sampler cannot attribute);
4. `loopDelayP99Ms >= 50` → `"io-bound"` (late callbacks with an idle loop);
5. otherwise `"healthy"`.

`nextStep` names the tool you would reach for next, and must be different for
every kind.

```ts
classifyBottleneck({ utilization: 0.92, loopDelayP99Ms: 180, gcShare: 0.05, topFrameSelfShare: 0.41 });
// { kind: "cpu-hot-spot", nextStep: "..." }
```

```
uv run dojo test node v3nc05_cpu_profiling review1
```

references.solution.ts:
// v3nc05_cpu_profiling / review1 - reference solution (author only, used by `dojo verify`).

export interface Signals {
  utilization: number;
  loopDelayP99Ms: number;
  gcShare: number;
  topFrameSelfShare: number;
}

export type Diagnosis =
  | { kind: "cpu-hot-spot"; nextStep: string }
  | { kind: "gc-pressure"; nextStep: string }
  | { kind: "blocking-call"; nextStep: string }
  | { kind: "io-bound"; nextStep: string }
  | { kind: "healthy"; nextStep: string };

// The order of these rules is the content. Several can be true at once - a
// GC-pressured process also shows high utilisation, because collection is CPU
// work - and only the most specific one is actionable. Thresholds are
// deliberately explicit so a team can tune them to their own normal.
export function classifyBottleneck(signals: Signals): Diagnosis {
  if (signals.gcShare >= 0.25) {
    return {
      kind: "gc-pressure",
      nextStep:
        "Take a heap snapshot and an allocation profile (--heap-prof): the fix is fewer or shorter-lived objects, not a faster function.",
    };
  }

  if (signals.utilization >= 0.7 && signals.topFrameSelfShare >= 0.3) {
    return {
      kind: "cpu-hot-spot",
      nextStep:
        "Sort the CPU profile by self time and change the top frame; if it cannot be made cheaper, move it to a worker thread.",
    };
  }

  if (signals.utilization >= 0.7) {
    return {
      kind: "blocking-call",
      nextStep:
        "Look for a synchronous call - readFileSync, a sync crypto or zlib call, a huge JSON.parse - and check max loop delay against p99; a sampler under-reports a rare long stall.",
    };
  }

  // Only reachable with utilisation below 0.7, because rule 3 catches the
  // busy case first. Whoever reorders these rules must preserve that.
  if (signals.loopDelayP99Ms >= 50) {
    return {
      kind: "io-bound",
      nextStep:
        "The loop is idle and callbacks are still late: check the libuv threadpool (UV_THREADPOOL_SIZE), downstream latency and cgroup CPU quota, then trace the request rather than profiling it.",
    };
  }

  return {
    kind: "healthy",
    nextStep:
      "No CPU signal worth chasing. If latency is still bad, the time is being spent outside this process - go to distributed tracing.",
  };
}
